import MiniSearch from "minisearch";
// Resolved relative to output/<Module>/ at build time (same convention as
// MarkdownContent.js). The index is generated by web/scripts/render-docs.mjs.
import index from "../../docs/out/search-index.json";

const mini = new MiniSearch({
  fields: ["heading", "text", "docTitle"],
  storeFields: ["path", "anchor", "docTitle", "heading", "text"],
  searchOptions: {
    boost: { heading: 3, docTitle: 2 },
    prefix: true,
    fuzzy: 0.2,
    combineWith: "AND",
  },
});
mini.addAll(index);

const escapeHtml = (s) =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

const escapeRegex = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

// Escape the text, then wrap occurrences of the matched terms in <mark>.
const highlight = (text, terms) => {
  const esc = escapeHtml(text);
  if (!terms.length) return esc;
  const re = new RegExp("(" + terms.map(escapeRegex).join("|") + ")", "gi");
  return esc.replace(re, "<mark>$1</mark>");
};

// A short context window around the first matching term in the section body.
const snippetOf = (text, terms) => {
  const lower = text.toLowerCase();
  let pos = -1;
  for (const t of terms) {
    const i = lower.indexOf(t.toLowerCase());
    if (i >= 0 && (pos < 0 || i < pos)) pos = i;
  }
  const start = pos < 0 ? 0 : Math.max(0, pos - 40);
  let s = text.slice(start, start + 180).trim();
  if (start > 0) s = "… " + s;
  if (start + 180 < text.length) s = s + " …";
  return s;
};

export const searchImpl = (query) => {
  const q = query.trim();
  if (!q) return [];
  return mini.search(q).slice(0, 40).map((r) => {
    const terms = r.terms && r.terms.length ? r.terms : q.split(/\s+/).filter(Boolean);
    return {
      path: r.path,
      anchor: r.anchor,
      docTitle: r.docTitle,
      heading: r.heading,
      headingHtml: highlight(r.heading, terms),
      snippetHtml: highlight(snippetOf(r.text || "", terms), terms),
    };
  });
};
